import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "Documents cannot be added to a vendor under review",
    { tag: "@DOC-06" },
    async ({ apiAs }) => {
      // Background: signed in as member, vendor in status "draft"
      const member = await apiAs("member");
      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC-06 Vendor"),
          category: "software",
          contact_email: `doc06.${Date.now()}.${Math.random().toString(36).slice(2, 8)}@northwind.test`,
        },
      });
      const vendor = await expectStatus<{ id: string; status: string }>(created, 201);
      expect(vendor.status).toBe("draft");

      // Given the vendor is in status "in_review"
      const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
      const submittedVendor = await expectStatus<{ id: string; status: string }>(submitted, 200);
      expect(submittedVendor.status).toBe("in_review");

      // When I upload "w9.txt" as kind "w9"
      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.txt",
            mimeType: "text/plain",
            buffer: Buffer.from("W-9 form contents for DOC-06 test"),
          },
        },
      });

      // Then the response status is 409 and the error code is "vendor_locked"
      const body = await expectStatus<{ error: { code: string } }>(upload, 409);
      expect(body.error.code).toBe("vendor_locked");
    },
  );
});
